import {FIELD_DEFS,createInitialState,recomputeRecords,filterEnterprises,exactQuery,getLineage,recordServiceCall,setFieldSourceOverride,clearFieldSourceOverride} from './core.mjs';
import {readTableFile,downloadCSV} from './file-reader.mjs';
import {TEMPLATE_HEADERS,validateTemplateRows,applyTemplateBatch} from './template-import.mjs';
import {upgradeSourceState,isConfigurableSource} from './source-config.mjs';
import {retainUploadedFile,openUploadedFile,discardUploadedFile} from './upload-history.mjs';
import {upgradeApiServices,handleApiServiceAction} from './api-services.mjs';
import {upgradeFtpSources,renderFtpSources,handleFtpAction,selectFtpSource} from './ftp-sources.mjs';
import {upgradeSubscriptions,handleSubscriptionAction} from './subscription-services.mjs';
import {renderDownstreamServices,downstreamCounts} from './downstream-services.mjs';
import {upgradeUpdateJobs,renderUpdateJobs,handleUpdateJobAction,handleUpdateJobFormEvent,dueUpdateJob} from './update-jobs.mjs';
import {executeUpdateJob} from './update-execution.mjs';

const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const label=k=>FIELD_DEFS.find(f=>f.key===k)?.label||k,format=v=>v==null||v===''?'—':Array.isArray(v)?v.join('、'):String(v),date=v=>v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'尚未运行';
const badge=(t,c='neutral')=>`<span class="badge ${c}">${esc(t)}</span>`,btn=(t,a,extra='',c='secondary')=>`<button class="btn ${c}" data-action="${a}" ${extra}>${t}</button>`;
const opts=(items,value='',blank='请选择')=>`<option value="">${blank}</option>`+items.map(i=>{const v=typeof i==='object'?i.value:i,t=typeof i==='object'?i.label:i;return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`;}).join('');
const unique=key=>[...new Set(state.records.flatMap(r=>Array.isArray(r[key])?r[key]:[r[key]]).filter(Boolean))].sort();
const card=(title,body,actions='')=>`<section class="card"><div class="card-header"><h2>${title}</h2>${actions}</div><div class="card-body">${body}</div></section>`;
const empty=(title,desc='')=>`<div class="empty-state"><div class="empty-icon">⌕</div><h3>${title}</h3><p>${desc}</p></div>`;
let state,revision=0,page=location.hash.slice(1)||'overview',sourceId='ftp_demo',sourceMode='ftp',downstreamMode='subscription',updatesTab='config',busy=false,queryValue='',queryResult=null,filters={},filterResults=null,inventorySearch='',selected=new Set(),scriptDraft=null,importRows=null,importFile=null;
const META={services:['下游服务','统一提供批量订阅推送与标准 API 服务。'],priorities:['信源排序','统一配置字段来源顺序，保存后对现有候选值重新融合。'],overview:['数据总览','从厂商接入到企业服务，查看每一步的数据流转。'],sources:['数据接入','通过 FTP/FTPS 与离线文件本地上传接入企业数据。'],scripts:['脚本管理','独立管理字段加工逻辑，发布后可在字段映射中绑定。'],updates:['更新任务','统一配置 FTP/FTPS 更新来源、方式、频率和执行时间，管理任务与运行记录。'],enterprises:['数据存储','接入后的统一企业库，为下游查询与订阅服务提供数据。'],screening:['企业批量筛选','按地区、行业、资质、规模和产业链节点组合筛选企业。'],query:['单企业精准查询','输入统一社会信用代码或企业全称，获取该企业工商详细信息。']};

async function jsonFetch(url,options){if(window.DATAHUB_TRANSPORT)return window.DATAHUB_TRANSPORT(url,options);const r=await fetch(url,{...options,headers:{'Content-Type':'application/json',...(options?.headers||{})}});const d=await r.json().catch(()=>({message:'服务器返回了无法读取的响应'}));if(!r.ok){const e=new Error(d.message||d.error||'请求失败');e.status=r.status;e.data=d;throw e;}return d;}
function upgradeWorkspace(workspace){upgradeSourceState(workspace);delete workspace.mappings.file;upgradeApiServices(workspace);upgradeFtpSources(workspace);upgradeSubscriptions(workspace);upgradeUpdateJobs(workspace);return workspace;}
async function save(){const result=await jsonFetch('/api/state',{method:'PUT',body:JSON.stringify({state,baseRevision:revision})});revision=result.revision;}
async function mutate(fn,message){if(busy)return false;busy=true;const before=structuredClone(state);try{await fn();await save();render();if(message)toast(message);return true;}catch(e){state=e.status===409&&e.data.state?e.data.state:before;if(e.status===409){revision=e.data.revision;upgradeWorkspace(state);closeModal();filterResults=null;queryResult=null;render();toast('配置已被其他窗口修改，已加载最新内容，请重新操作。','error');}else toast(e.message,'error');return false;}finally{busy=false;}}
function toast(message,type='success'){const d=document.createElement('div');d.className=`toast ${type}`;d.textContent=message;$('#toast-root').append(d);setTimeout(()=>d.remove(),5000);}
function showModal(title,body,footer='',wide=false){$('#modal-root').innerHTML=`<div class="modal-overlay" data-dismiss="true"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-header"><h2>${esc(title)}</h2><button class="modal-close" data-action="close" aria-label="关闭">×</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</section></div>`;associateLabels();}
function closeModal(){$('#modal-root').innerHTML='';importRows=null;importFile=null;}
function associateLabels(){document.querySelectorAll('.form-field').forEach((field,i)=>{const l=field.querySelector('label'),control=field.querySelector('input,select,textarea,output');if(l&&control&&!l.contains(control)){control.id ||= 'control-'+(control.name||i)+'-'+i;l.htmlFor=control.id;}});}
function heading(){const m=META[page]||META.overview;$('#page-heading').innerHTML=`<span class="eyebrow">ENTERPRISE DATA WORKSPACE</span><h1>${m[0]}</h1><p class="subtle">${m[1]}</p>`;$('#header-actions').innerHTML=page==='overview'?'':page==='sources'?'':page==='scripts'?btn('新建转换脚本','new-script','','primary'):page==='updates'?'':page==='enterprises'?btn('按条件筛选','go','data-page="screening"','primary'):badge(`数据版本 V${state.dataVersion}`,'blue');document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===page));}
function render(){heading();const renders={overview:renderOverview,sources:renderSources,priorities:renderPriorities,services:()=>renderDownstreamServices(state,downstreamMode),scripts:renderScripts,updates:renderUpdates,enterprises:renderInventory,screening:renderScreening,query:renderQuery};$('#page-content').innerHTML=(renders[page]||renderOverview)();associateLabels();}
function go(next){page=next;location.hash=next;closeModal();selected.clear();render();window.scrollTo(0,0);}
const notice=()=>`<div class="inline-notice"><span class="badge blue">演示数据</span><span>企业及 DEMO 开头的代码均为虚构标识；配置、加工、更新和查询结果会实际保存。</span></div>`;
function renderOverview(){const api=state.providers.filter(p=>isConfigurableSource(p)&&p.enabled),last=state.tasks[0],counts=downstreamCounts(state),published=counts.subscription+counts.api;return notice()+`<div class="stats-grid">${[['企业数据总量',state.records.length,'家企业','统一主体 · 可筛选可查询'],['可用信源',api.length,'个来源',api.map(p=>p.name).join(' / ')],['标准字段',FIELD_DEFS.length,'个字段','工商信息与专题补充'],['已发布下游服务',published,'个服务',`订阅 ${counts.subscription} · API ${counts.api}`]].map(([t,n,u,d],i)=>`<div class="stat-card"><div class="stat-label">${t}</div><div class="stat-value">${n}<span>${u}</span></div><div class="stat-footer">${esc(d)}</div><span class="stat-icon">${['▦','⇄','≡','⌕'][i]}</span></div>`).join('')}</div><div class="card pipeline-card"><div class="card-header"><h2>数据处理链路</h2>${badge('从信源到下游服务','success')}</div><div class="pipeline">${[['01','接入数据',`${state.rawRecords.length} 条来源记录`,'sources'],['02','映射与加工',`${state.scripts.filter(s=>s.status==='published').length} 个已发布脚本`,'scripts'],['03','融合与更新',`${state.tasks.length} 次处理记录`,'updates'],['04','下游服务与发布',`${published} 个已发布服务`,'services']].map(([n,t,d,p])=>`<button class="pipeline-step" data-action="go" data-page="${p}"><span class="step-number">${n}</span><h3>${t}</h3><p>${d}</p></button>`).join('')}</div></div><div class="grid-two section-gap">${card('数据源运行情况',sourceTable(),btn('管理数据接入 →','go','data-page="sources"','ghost'))}${card('最近更新',last?`<div class="update-summary">${badge(statusText(last.status),last.failed?'warning':'success')}<h3>${esc(last.sourceName)} · ${last.mode==='full'?'全量更新':'增量更新'}</h3><p class="subtle">${date(last.completedAt)}</p><div class="mini-stats"><span>新增 <b>${last.added}</b></span><span>变化 <b>${last.updated}</b></span><span>未变化 <b>${last.unchanged}</b></span></div>${btn('查看处理明细','task-detail',`data-id="${last.id}"`,'ghost')}</div>`:empty('暂无更新任务'),btn('全部任务 →','go','data-page="updates"','ghost'))}</div><div class="section-gap">${card('下游服务',`<div class="service-grid">${[['subscription','批量订阅推送','按国民经济行业、注册地区、荣誉资质订阅',counts.subscription],['api','标准 API 服务','封装企业批量筛选、单企业精准查询接口',counts.api]].map(([mode,name,description,count])=>`<div class="service-card"><h3>${name}</h3><p>${description}</p>${badge(`${count} 个已发布`,'blue')}${btn('管理服务 →','downstream-open',`data-mode="${mode}"`,'ghost')}</div>`).join('')}</div>`)}</div>`;}
function statusText(v){return ({success:'处理完成',partial:'部分成功',failed:'处理失败'})[v]||v;}
function sourceTable(){return `<div class="table-wrap"><table><thead><tr><th>数据源</th><th>接入方式</th><th>来源记录</th><th>状态</th></tr></thead><tbody>${state.providers.filter(isConfigurableSource).map(p=>`<tr><td><button class="text-button" data-action="source-select" data-source="${p.id}">${esc(p.name)}</button></td><td>${p.type==='ftp'?'FTP/FTPS 对接':'离线文件本地上传'}</td><td>${state.rawRecords.filter(r=>r.sourceId===p.id).length}</td><td>${badge(!p.enabled?'已停用':p.type==='file'?'可上传':'演示可运行',!p.enabled?'neutral':'success')}</td></tr>`).join('')}</tbody></table></div>`;}
const sourceName=id=>state.providers.find(p=>p.id===id)?.name||id;
function renderSources(){if(!['ftp','file'].includes(sourceMode))sourceMode='ftp';return `<div class="access-tabs tabs"><button class="tab ${sourceMode==='ftp'?'active':''}" data-action="access-mode" data-mode="ftp">FTP/FTPS 对接</button><button class="tab ${sourceMode==='file'?'active':''}" data-action="access-mode" data-mode="file">离线文件本地上传</button></div>`+(sourceMode==='file'?renderFileSources():renderFtpSources(state));}
function renderPriorities(){return `<div class="inline-notice">字段级规则对 FTP/FTPS 信源和离线文件本地上传统一生效。自动取值按从左到右选择首个非空值；单企业手动指定的字段优先采用所选来源，恢复自动后重新跟随此排序。历史停用信源仅保留已入库值与血缘。</div>`+card('信源排序',priorityPanel());}
function renderFileSources(){return `<section class="card"><div class="card-body"><div class="source-file-toolbar"><div><h2>离线文件本地上传</h2><p class="subtle">请按固定模板填写并上传，无需配置字段映射。原件可通过下方文件链接下载。共 ${state.uploadRecords.length} 条上传记录。</p></div><div class="actions">${btn('下载 CSV 模板','template')}${btn('离线文件本地上传','import-dialog','','primary')}</div></div>${state.uploadRecords.length?`<div class="table-wrap section-gap"><table class="file-history-table"><thead><tr><th>信源名称</th><th>文件链接</th><th>上传时间</th><th>数据行数</th><th>处理结果</th><th></th></tr></thead><tbody>${state.uploadRecords.map(r=>`<tr><td><strong>${esc(r.sourceName)}</strong></td><td><button class="text-button file-link" data-action="open-upload" data-id="${r.fileId}">${esc(r.name)}</button><div class="file-meta">${(r.size/1024).toFixed(1)} KB · 原始文件</div></td><td class="file-time">${date(r.uploadedAt)}</td><td>${r.rowCount}</td><td>${badge(statusText(r.status),r.status==='success'?'success':'warning')}<div class="subtle">新增 ${r.added||0} · 更新 ${r.updated||0} · 失败 ${r.failed||0}</div></td><td>${btn('任务明细','task-detail',`data-id="${r.taskId}"`,'ghost small')}</td></tr>`).join('')}</tbody></table></div>`:empty('暂无上传文件记录','点击“上传本地文件”，完成检查与导入后展示信源名称、原件链接和处理结果。')}</div></section>`;}
function priorityPanel(){const providers=state.providers.filter(isConfigurableSource),ids=providers.map(p=>p.id);return `<div class="toolbar"><div><h3>字段级来源顺序</h3><p class="subtle">高优先级为空时回退下一来源，保存后立即重新融合已有候选值。历史停用来源仅作无有效值时的回退，不提供新排序配置；既有手动来源保留。</p></div>${btn('保存并重新融合','save-priority','','primary')}</div><div class="table-wrap"><table><thead><tr><th>标准字段</th>${ids.map((id,i)=>`<th>第 ${i+1} 优先级</th>`).join('')}</tr></thead><tbody>${FIELD_DEFS.map(f=>{const order=[...new Set([...(state.priorities[f.key]||[]).filter(id=>ids.includes(id)),...ids])];return `<tr data-priority="${f.key}"><td>${f.label}</td>${order.map(id=>`<td><select aria-label="${esc(f.label)}来源优先级">${opts(providers.map(p=>({value:p.id,label:p.name})),id)}</select></td>`).join('')}</tr>`;}).join('')}</tbody></table></div>`;}
function renderScripts(){return `<div class="inline-notice"><span class="badge blue">独立管理</span><span>脚本经过测试与发布后，再到字段映射选择使用。新版本不会自动替换当前绑定。</span></div>${card('转换脚本',`<div class="table-wrap"><table><thead><tr><th>脚本名称</th><th>版本</th><th>状态</th><th>映射引用</th><th>说明</th><th>操作</th></tr></thead><tbody>${state.scripts.map(s=>`<tr><td><strong>${esc(s.name)}</strong><div class="subtle mono">${esc(s.id)}</div></td><td>V${s.version}</td><td>${badge(s.status==='published'?'已发布':'草稿',s.status==='published'?'success':'warning')}</td><td>${state.providers.filter(isConfigurableSource).flatMap(p=>state.mappings[p.id]||[]).filter(m=>m.scriptId===s.id).length} 处</td><td>${esc(s.description)}</td><td>${btn(s.status==='published'?'查看 / 新建版本':'编辑 / 发布','edit-script',`data-id="${s.id}"`,'ghost small')}</td></tr>`).join('')}</tbody></table></div>`)}`;}
function scriptDialog(id){const s=id?state.scripts.find(s=>s.id===id):null;scriptDraft=s?structuredClone(s):{id:'script_'+crypto.randomUUID().slice(0,8),name:'',version:1,status:'draft',description:'',code:'return String(value ?? "").trim();'};showModal(s?.status==='published'?'查看脚本与创建新版本':'编辑转换脚本',`<form id="script-form" class="form-grid"><div class="form-field"><label>脚本名称</label><input name="name" value="${esc(scriptDraft.name)}" required></div><div class="form-field"><label>当前版本</label><input value="V${scriptDraft.version} · ${scriptDraft.status==='published'?'已发布':'草稿'}" readonly></div><div class="form-field full"><label>处理说明</label><input name="description" value="${esc(scriptDraft.description)}"></div><div class="form-field full"><label>脚本内容 JavaScript</label><small>参数 value 为原始值，record 为当前来源记录；用 return 返回转换结果。</small><textarea class="code-editor" name="code" rows="9" spellcheck="false">${esc(scriptDraft.code)}</textarea></div><div class="form-field"><label>测试输入值</label><input name="testValue" value="150000000" placeholder="可输入数字、字符串或JSON数组"></div><div class="form-field"><label>测试结果</label><output id="script-result">尚未测试</output></div></form>`,btn('测试脚本','test-script')+btn(s?.status==='published'?'另存为草稿版本':'保存草稿','save-script')+(s?.status==='draft'?btn('测试并发布','publish-script','','primary'):''),true);}
function renderUpdates(){
  const tabs=`<div class="tabs access-tabs" role="tablist" aria-label="更新任务视图">${[['config','任务配置'],['execution','任务执行']].map(([key,title])=>`<button id="updates-tab-${key}" class="tab ${updatesTab===key?'active':''}" role="tab" aria-selected="${updatesTab===key}" aria-controls="updates-panel" data-action="updates-tab" data-tab="${key}">${title}</button>`).join('')}</div>`;
  const content=updatesTab==='execution'?card('任务执行记录',`<p class="subtle">按已保存的任务配置运行，查看每次执行结果、处理数量和明细。</p><div class="section-gap">${state.tasks.length?taskTable(state.tasks):empty('暂无执行记录','选择已启用的任务运行后，可在此查看处理结果。')}</div>`,btn('运行任务','run-dialog','','primary')):renderUpdateJobs(state);
  return tabs+`<div id="updates-panel" role="tabpanel" aria-labelledby="updates-tab-${updatesTab}">${content}</div>`;
}
function taskTable(tasks){return `<div class="table-wrap"><table><thead><tr><th>任务 / 来源</th><th>更新方式</th><th>完成时间</th><th>新增</th><th>变化</th><th>未变</th><th>失败</th><th>状态</th><th></th></tr></thead><tbody>${tasks.map(t=>`<tr><td><strong>${esc(t.jobName||t.sourceName)}</strong>${t.jobName?`<div class="subtle">${esc(t.sourceName)}</div>`:''}<div class="subtle mono">${t.id}</div></td><td>${t.mode==='full'?'全量更新':'增量更新'}</td><td>${date(t.completedAt)}</td><td>${t.added}</td><td>${t.updated}</td><td>${t.unchanged}</td><td>${t.failed}</td><td>${badge(statusText(t.status),t.status==='failed'?'danger':t.status==='partial'?'warning':'success')}</td><td>${btn('明细','task-detail',`data-id="${t.id}"`,'ghost small')}</td></tr>`).join('')}</tbody></table></div>`;}
function enterpriseTable(records,selectable=false){return records.length?`<div class="table-wrap"><table><thead><tr>${selectable?'<th><input type="checkbox" data-select-all aria-label="选择全部结果"></th>':''}<th>企业名称 / 信用代码</th><th>地区</th><th>行业</th><th>资质</th><th>规模</th><th>产业链节点</th><th></th></tr></thead><tbody>${records.map(r=>`<tr>${selectable?`<td><input type="checkbox" data-select-id="${r.id}" ${selected.has(r.id)?'checked':''} aria-label="选择${esc(r.enterpriseName)}"></td>`:''}<td><button class="text-button font-medium" data-action="detail" data-id="${r.id}">${esc(r.enterpriseName)}</button><div class="subtle mono">${esc(r.creditCode)}</div></td><td>${esc((r.regionCity||'')+' '+(r.regionDistrict||''))}</td><td>${esc(r.industry||'—')}</td><td><div class="chips">${(r.qualifications||[]).map(v=>`<span class="chip blue">${esc(v)}</span>`).join('')||'—'}</div></td><td>${esc(r.scale||'—')}</td><td><div class="chips">${(r.chainNodes||[]).map(v=>`<span class="chip">${esc(v)}</span>`).join('')||'—'}</div></td><td>${btn('工商详情','detail',`data-id="${r.id}"`,'ghost small')}</td></tr>`).join('')}</tbody></table></div>`:empty('没有符合条件的企业','请调整筛选条件，或接入新的企业数据。');}
function renderInventory(){const rows=state.records.filter(r=>!inventorySearch||r.enterpriseName.includes(inventorySearch)||r.creditCode.includes(inventorySearch));return notice()+card('统一企业库',`<div class="toolbar"><div class="search-input"><input id="inventory-search" placeholder="搜索企业名称或代码" value="${esc(inventorySearch)}">${btn('搜索','inventory-search','','small')}</div><span class="subtle">共 ${rows.length} 家 · ${state.rawRecords.length} 条来源记录</span></div>${enterpriseTable(rows)}`);}
const filterFields=[['regionProvince','地区 · 省份'],['regionCity','城市'],['industry','所属行业'],['qualifications','企业资质'],['scale','企业规模'],['chainNodes','产业链节点']];
function renderScreening(){return `<div class="service-banner"><div>${badge('服务 01','blue')}<h2>企业批量筛选</h2><p>不同维度同时满足，多值标签按所选项匹配。</p></div><span class="service-code">BATCH SCREENING</span></div><section class="card section-gap"><div class="card-body"><form id="filter-form" class="form-grid three">${filterFields.map(([key,t])=>`<div class="form-field"><label>${t}</label><select name="${key}">${opts(unique(key),filters[key]||'','不限')}</select></div>`).join('')}</form><div class="panel-actions">${btn('筛选企业','filter','','primary')}${btn('重置条件','reset-filters')}</div></div></section><section class="card section-gap"><div class="card-header"><div><h2>筛选结果 ${filterResults?`<span class="count">${filterResults.length}</span>`:''}</h2><p class="subtle">${filterResults?'可查看企业详情，或导出全部 / 已选企业。':'设置条件后运行筛选，结果来自当前统一企业库。'}</p></div>${btn('导出结果 CSV','export-filter',filterResults?.length?'':'disabled')}</div><div id="filter-results">${filterResults?enterpriseTable(filterResults,true):empty('选择条件，开始筛选企业','地区、行业、资质、规模、产业链节点可自由组合。')}</div></section>`;}
function renderQuery(){return `<div class="service-banner"><div>${badge('服务 02','blue')}<h2>单企业精准查询</h2><p>按企业全称或统一社会信用代码完全匹配，不返回模糊候选。</p></div><span class="service-code">EXACT COMPANY QUERY</span></div><section class="card section-gap"><div class="card-body"><form id="query-form" class="query-search"><div class="form-field"><label>企业全称 / 统一社会信用代码</label><input id="query-input" autocomplete="off" value="${esc(queryValue)}" placeholder="请输入完整企业名称或统一社会信用代码"></div>${btn('精准查询','query','','primary large')}</form><div class="query-examples"><span class="subtle">演示查询：</span>${state.records.slice(0,2).map(r=>`<button class="chip" data-action="fill-query" data-id="${r.id}">${esc(r.enterpriseName)}</button>`).join('')}</div></div></section><div class="section-gap">${queryResult?.status==='found'?detailsPanel(queryResult.record,true):queryResult?card('查询结果',empty('未找到完全匹配的企业',queryResult.message)):card('工商详细信息',empty('等待查询','查询结果包含工商信息、专题补充和字段来源。'))}</div>`;}
function detailsPanel(r,inPage=false){const basic=FIELD_DEFS.filter(f=>f.group==='工商信息'),topic=FIELD_DEFS.filter(f=>f.group!=='工商信息');const grid=defs=>`<div class="detail-grid">${defs.map(f=>`<div class="detail-item ${f.key==='businessScope'?'full':''}"><label>${f.label}${r.lineage[f.key]?.selected?`<button class="text-button" data-action="lineage" data-id="${r.id}" data-field="${f.key}" title="查看字段来源">↗ 来源</button>`:''}</label><span>${esc(format(r[f.key]))}${r.lineage[f.key]?.manualRequested?`<small class="manual-source-note">${r.lineage[f.key].manualApplied?'手动来源：':'手动来源不可用，自动回退：'}${esc(sourceName(r.lineage[f.key].requestedSourceId))}</small>`:''}</span></div>`).join('')}</div>`;return `<div class="company-header"><div class="company-avatar">企</div><div><h2>${esc(r.enterpriseName)}</h2><p class="subtle mono">${esc(r.creditCode)}</p></div>${badge(r.synthetic?'虚构演示企业':r.registrationStatus||'已入库',r.synthetic?'blue':'success')}</div>${card('工商详细信息',grid(basic))}<div class="section-gap">${card('专题补充',grid(topic)+'<p class="subtle section-gap">资质、规模、产业链节点由专题文件补充，与工商来源分开管理。</p>')}</div><p class="subtle section-gap">中心企业 ID：${esc(r.id)} · 数据更新时间：${date(r.updatedAt)} · 数据来源：${r.sources.map(sourceName).join('、')}</p>`;}
function taskDetail(id){
 const t=state.tasks.find(t=>t.id===id);if(!t)return toast('任务记录不存在','error');
 const snapshot=t.scopeSnapshot,results=t.targetResults||[];
 const details=[['任务编号',t.id],['任务名称',t.jobName||'手动接入'],['数据来源',t.sourceName],['更新机制',t.mode==='full'?'全量更新':'增量更新'],['处理状态',statusText(t.status)],['接收记录',t.received],['中心新增企业',t.newEnterprises],['中心变化企业',t.changedEnterprises],['未变化来源记录',t.unchanged],['变更窗口起点',date(t.windowStart)],['变更窗口终点',date(t.windowEnd)]];
 if(snapshot)details.push(['更新企业范围',snapshot.summary],['冻结目标企业',snapshot.total+' 家'],['范围固定时间',date(snapshot.frozenAt)],['目标请求次数',t.requested??0],['成功目标企业',t.successTargets??0],['失败目标企业',t.failedTargets??0]);
 const scopeHtml=snapshot?`<h3 class="section-gap">本次固定企业范围与逐企结果</h3><p class="subtle">本次执行使用以下固定名单；后续企业数据或筛选条件变化不会改写历史记录。请求次数按企业目标统计，分页和重试次数以接口调用日志为准。</p><div class="table-wrap scope-result-table"><table><thead><tr><th>企业全称</th><th>统一社会信用代码</th><th>名单行号</th><th>采集方式</th><th>执行结果</th><th>接收记录</th><th>说明</th></tr></thead><tbody>${results.map(r=>`<tr><td>${esc(r.enterpriseName||'待厂商返回')}</td><td>${esc(r.creditCode||'待厂商确认')}</td><td>${esc(r.scopeRow??'—')}</td><td>${r.baseline?'完整采集':'增量采集'}</td><td>${badge(r.status==='success'?'成功':r.status==='failed'?'失败':'待执行',r.status==='success'?'success':r.status==='failed'?'warning':'neutral')}</td><td>${esc(r.received)}</td><td>${esc(r.message)}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">本次范围没有匹配企业，未发起 API 请求。</td></tr>'}</tbody></table></div>`:'';
 showModal('任务处理明细',`<div class="detail-grid">${details.map(([k,v])=>`<div class="detail-item"><label>${k}</label><span>${esc(v)}</span></div>`).join('')}</div><p class="subtle section-gap">${esc(t.message)}</p><p class="subtle">${esc(t.scope)}</p>${scopeHtml}${t.errors?.length?`<h3 class="section-gap">失败记录</h3><pre>${esc(JSON.stringify(t.errors,null,2))}</pre>`:''}`,btn('关闭','close'),true);
}
function lineageDialog(id,field){
  const l=getLineage(state,id,field),record=state.records.find(r=>r.id===id),manual=Boolean(l.manualRequested);
  const mode=manual?(l.manualApplied?`已手动指定：${sourceName(l.requestedSourceId)}`:`手动来源暂不可用，已自动回退：${sourceName(l.requestedSourceId)}`):'自动按信源排序取值';
  showModal(label(field)+' · 取值来源',`<div class="inline-notice"><span class="badge ${manual?'blue':'neutral'}">${manual?'手动选择':'自动取值'}</span><span>${esc(mode)}。切换仅影响当前企业的当前字段，保存后下游查询和订阅使用新取值。</span></div><p class="subtle section-gap">${esc(l.rule)}${l.candidates.some(c=>state.providers.some(p=>p.id===c.sourceId&&(p.retired||p.type==='api')))?' 历史停用来源仅保留已有值与血缘，不可新增手动选择；自动融合时优先采用可用来源，均无有效值时再回退历史候选。':''}</p><div class="table-wrap section-gap"><table><thead><tr><th>来源优先级</th><th>来源字段</th><th>候选值</th><th>来源时间</th><th>结果 / 切换来源</th></tr></thead><tbody>${l.candidates.map(c=>`<tr><td>${c.priority}. ${esc(c.sourceName)}${state.providers.some(p=>p.id===c.sourceId&&(p.retired||p.type==='api'))?badge('历史停用来源'):''}</td><td class="mono">${esc(c.rawField)}</td><td>${esc(format(c.value))}</td><td>${date(c.sourceUpdatedAt)}</td><td class="source-choice-cell">${badge(c.selected?(l.manualApplied?'当前取值 · 手动':'当前取值'):c.empty?'空值回退':c.valid===false?'不可用':'保留候选',c.selected?'success':'neutral')}${isConfigurableSource(state.providers.find(p=>p.id===c.sourceId))&&!c.empty&&c.valid!==false&&!(c.selected&&l.manualApplied)?btn(c.selected?'固定此来源':'切换为此来源','choose-field-source',`data-id="${id}" data-field="${field}" data-source="${esc(c.sourceId)}" aria-label="采用${esc(c.sourceName)}的${esc(label(field))}"`,'ghost small'):''}${c.invalidReason?`<small class="subtle">${esc(c.invalidReason)}</small>`:''}</td></tr>`).join('')}</tbody></table></div><p class="subtle section-gap">手动选择跟随该来源后续最新的有效值；来源为空或不可用时按自动规则回退。恢复自动取值后重新使用「信源排序」。不修改来源原始记录和其他企业。</p>`,btn('恢复自动取值','clear-field-source',`data-id="${id}" data-field="${field}" ${manual?'':'disabled'}`)+btn('配置信源排序','go-priority'),true);
}
function runWorker(jobs){return new Promise((resolve,reject)=>{const worker=new Worker(new URL('./script-worker.js',import.meta.url));const timer=setTimeout(()=>{worker.terminate();reject(new Error('脚本执行超过2秒，已终止'));},2000);worker.onmessage=e=>{clearTimeout(timer);worker.terminate();resolve(e.data.results);};worker.onerror=e=>{clearTimeout(timer);worker.terminate();reject(new Error(e.message||'脚本执行失败'));};worker.postMessage({jobs});});}
async function buildRunner(rows,mappings,id=sourceId){const jobs=[];rows.forEach((row,index)=>mappings.filter(m=>m.enabled!==false&&m.scriptId).forEach(m=>{const s=state.scripts.find(s=>s.id===m.scriptId&&s.status==='published');if(!s)throw new Error('存在未发布脚本');const value=m.sourceField.split('.').reduce((v,k)=>v?.[k],row);jobs.push({index,target:m.targetField,code:s.code,value,row,context:{sourceId:id,targetField:m.targetField}});}));const results=jobs.length?await runWorker(jobs):[],lookup=new Map(results.map(r=>[r.index+':'+r.target,r]));return (script,value,ctx)=>{const idx=rows.indexOf(ctx.row),out=lookup.get(idx+':'+ctx.targetField);if(!out)throw new Error('脚本预处理结果缺失');if(out.error)throw new Error(out.error);return out.value;};}
function runDialog(){
  const jobs=state.updateJobs.filter(job=>job.enabled&&!job.retired&&state.providers.some(p=>p.id===job.sourceId&&p.type==='ftp'&&!p.retired)&&(page!=='sources'||job.sourceId===sourceId));
  if(!jobs.length){showModal('运行更新任务','<p class="subtle">当前没有可执行任务。请在更新任务中新增任务，选择更新来源、更新方式、频率与执行时间后再运行。</p>',btn('新增更新任务','update-job-create',`data-source-id="${sourceId||''}"`,'primary'));return;}
  showModal('运行更新任务',`<form id="run-form" class="form-grid"><div class="form-field full"><label>选择更新任务</label><select name="jobId">${opts(jobs.map(job=>({value:job.id,label:`${job.name} · ${sourceName(job.sourceId)} · ${job.mode==='full'?'全量':'增量'}`})),jobs[0].id)}</select><small>来源、方式、频率和执行时间均在更新任务中集中配置。本次使用已保存配置运行。</small></div></form><div id="run-status" class="section-gap"></div>`,btn('取消','close')+btn('执行并入库','execute-run','','primary'));
}
async function runUpdateJob(id,{scheduled=false}={}){
 if(busy)return false;let result;
 const ok=await mutate(async()=>{result=await executeUpdateJob(state,id,{runScript:buildRunner});});
 if(ok){if(!scheduled){updatesTab='execution';go('updates');}toast((scheduled?'计划任务 · ':'')+result.task.message,result.task.failed?'warning':'success');}return ok;
}
async function executeRun(){const id=new FormData($('#run-form')).get('jobId');return runUpdateJob(id);}
function importDialog(){showModal('离线文件本地上传',`<div class="form-field"><label>信源名称</label><input id="upload-source-name" value="离线专题文件" placeholder="例如：企业资质名录、业务系统导出"></div><p class="subtle section-gap">支持 CSV / XLSX。原件、上传时间及处理结果将保存到离线文件本地上传记录；每行一家企业，按下载模板的固定字段直接入库，无需配置字段映射或加工脚本。企业全称和信用代码必填，其余列可留空。</p><div class="form-field section-gap"><label>选择表格文件</label><input id="table-file" type="file" accept=".xlsx,.csv"></div><div id="import-preview" class="section-gap"></div>`,btn('下载 CSV 模板','template')+btn('检查并预览','preview-import')+btn('上传并导入','execute-import','disabled','primary'),true);}
async function handleAction(action,b){
  const serviceContext={getState:()=>state,mutate,toast,showModal,closeModal,render};
  if(action==='updates-tab'){updatesTab=b.dataset.tab==='execution'?'execution':'config';return render();}
  if(action.startsWith('update-job-')){if(action==='update-job-create'){updatesTab='config';if(page!=='updates')go('updates');}return handleUpdateJobAction(action,b,{...serviceContext,runJob:runUpdateJob});}
  if(action.startsWith('ftp-'))return handleFtpAction(action,b,{...serviceContext,runScript:buildRunner});
  if(action.startsWith('subscription-'))return handleSubscriptionAction(action,b,serviceContext);
  if(action==='downstream-mode'){downstreamMode=b.dataset.mode==='api'?'api':'subscription';return render();}
  if(action==='downstream-open'){downstreamMode=b.dataset.mode==='api'?'api':'subscription';return go('services');}
  if(action.startsWith('api-service-'))return handleApiServiceAction(action,b,{getState:()=>state,mutate,toast,showModal,closeModal});
  if(action==='choose-field-source'||action==='clear-field-source'){
    const id=b.dataset.id,field=b.dataset.field;
    const ok=await mutate(()=>{if(action==='choose-field-source')setFieldSourceOverride(state,id,field,b.dataset.source);else clearFieldSourceOverride(state,id,field);},action==='choose-field-source'?'已保存当前字段信源，下游服务将使用新取值':'已恢复自动按信源排序取值');
    if(ok){if(filterResults)filterResults=filterEnterprises(state,filters);if(queryResult)queryResult=exactQuery(state,queryValue);render();lineageDialog(id,field);}return;
  }
  if(action==='access-mode'){sourceMode=b.dataset.mode==='file'?'file':'ftp';sourceId=sourceMode==='file'?'file':state.providers.find(p=>p.type===sourceMode)?.id;return render();}
  if(action==='open-upload'){const record=state.uploadRecords.find(r=>r.fileId===b.dataset.id);return openUploadedFile(record);}
if(action==='go')return go(b.dataset.page);if(action==='close')return closeModal();if(action==='source-select'){const provider=state.providers.find(p=>p.id===b.dataset.source&&isConfigurableSource(p));if(!provider)return;sourceId=provider.id;sourceMode=provider.type;if(sourceMode==='ftp')selectFtpSource(sourceId);return go('sources');}if(action==='source-schedule')return go('updates');if(action==='go-priority')return go('priorities');if(action==='run-dialog')return runDialog();if(action==='execute-run')return executeRun();if(action==='new-script')return scriptDialog();if(action==='edit-script')return scriptDialog(b.dataset.id);if(action==='detail'){const r=state.records.find(r=>r.id===b.dataset.id);return showModal('企业工商档案',detailsPanel(r),btn('关闭','close'),true);}if(action==='lineage')return lineageDialog(b.dataset.id,b.dataset.field);if(action==='task-detail')return taskDetail(b.dataset.id);if(action==='import-dialog')return importDialog();if(action==='template'){return downloadCSV('企业专题数据模板.csv',TEMPLATE_HEADERS,state.records.slice(0,3).map(r=>[r.enterpriseName,r.creditCode,r.qualifications,r.scale,r.chainNodes,new Date().toISOString()]));}

  if(action==='save-priority'){const rules={},ids=state.providers.filter(isConfigurableSource).map(p=>p.id);document.querySelectorAll('[data-priority]').forEach(row=>{const order=[...row.querySelectorAll('select')].map(e=>e.value);if(order.some(v=>!ids.includes(v))||new Set(order).size!==ids.length)throw new Error(label(row.dataset.priority)+'的来源必须各不相同');const old=state.priorities[row.dataset.priority]||[];rules[row.dataset.priority]=order.concat(old.filter(id=>!ids.includes(id)));});return mutate(()=>{state.priorities=rules;recomputeRecords(state);state.dataVersion++;},'信源排序已保存，企业库已重新融合');}

  if(action==='test-script'||action==='publish-script'){const f=new FormData($('#script-form'));let input=f.get('testValue');try{input=JSON.parse(input);}catch{}const results=await runWorker([{index:0,target:'test',code:f.get('code'),value:input,row:{},context:{}}]);if(results[0].error){$('#script-result').textContent=results[0].error;throw new Error(results[0].error);}$('#script-result').textContent=JSON.stringify(results[0].value);if(action==='publish-script')await saveScript(true);}
  if(action==='save-script')return saveScript(false);
  if(action==='inventory-search'){inventorySearch=$('#inventory-search').value.trim();return render();}
  if(action==='filter'){filters=Object.fromEntries(new FormData($('#filter-form')));filterResults=filterEnterprises(state,filters);selected.clear();return mutate(()=>recordServiceCall(state,{type:'batch_filter',filters,resultCount:filterResults.length}),'筛选完成：'+filterResults.length+' 家企业');}
  if(action==='reset-filters'){filters={};filterResults=null;selected.clear();return render();}
  if(action==='export-filter'){const rows=selected.size?filterResults.filter(r=>selected.has(r.id)):filterResults;if(!rows?.length)throw new Error('没有可导出的企业');return downloadCSV('企业筛选结果.csv',FIELD_DEFS.map(f=>f.label),rows.map(r=>FIELD_DEFS.map(f=>r[f.key])));}
  if(action==='fill-query'){queryValue=state.records.find(r=>r.id===b.dataset.id).enterpriseName;queryResult=null;return render();}if(action==='query'){queryValue=$('#query-input').value.trim();queryResult=exactQuery(state,queryValue);if(queryResult.status==='invalid')throw new Error(queryResult.message);return mutate(()=>recordServiceCall(state,{type:'exact_query',query:queryValue,resultCount:queryResult.status==='found'?1:0}));}

  if(action==='preview-import'){const file=$('#table-file').files[0];if(!file)throw new Error('请先选择文件');const rows=await readTableFile(file),v=validateTemplateRows(rows);if(!v.valid)throw new Error(v.errors.join('；'));importRows=rows;importFile=file;$('#import-preview').innerHTML=`${badge(`已读取 ${rows.length} 行`,'success')}<pre class="code-editor">${esc(JSON.stringify(rows.slice(0,3),null,2))}</pre>`;document.querySelector('[data-action="execute-import"]').disabled=false;return;}
  if(action==='execute-import'){if(!importRows||!importFile)throw new Error('请先检查并预览文件');if(busy)return;const rows=importRows,file=importFile,name=$('#upload-source-name').value.trim();if(!name)throw new Error('请填写信源名称');let retained,task;const ok=await mutate(async()=>{retained=await retainUploadedFile(file);({task}=applyTemplateBatch(state,{rows}));state.uploadRecords.unshift({...retained,sourceName:name,rowCount:rows.length,taskId:task.id,status:task.status,added:task.added,updated:task.updated,failed:task.failed});});if(!ok&&retained)await discardUploadedFile(retained.fileId);if(ok){closeModal();sourceMode='file';sourceId='file';go('sources');toast('文件原件与上传记录已保存；'+task.message,task.failed?'warning':'success');}return;}

}
async function saveScript(publish){const f=new FormData($('#script-form'));if(!String(f.get('name')).trim())throw new Error('请填写脚本名称');return mutate(()=>{let s={...scriptDraft,name:String(f.get('name')).trim(),description:f.get('description'),code:f.get('code'),status:publish?'published':'draft'};if(scriptDraft.status==='published'){s.id=scriptDraft.id+'_v'+(scriptDraft.version+1)+'_'+crypto.randomUUID().slice(0,4);s.version=scriptDraft.version+1;s.parentId=scriptDraft.id;}const idx=state.scripts.findIndex(x=>x.id===s.id);if(idx>=0)state.scripts[idx]=s;else state.scripts.push(s);closeModal();},publish?'脚本已发布，可在字段映射中绑定':'草稿已保存');}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-nav]');if(nav){go(nav.dataset.nav);return;}const b=e.target.closest('[data-action]');if(b){e.preventDefault();Promise.resolve(handleAction(b.dataset.action,b)).catch(err=>toast(err.message,'error'));}else if(e.target.dataset.dismiss==='true')closeModal();});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='query-form')Promise.resolve(handleAction('query')).catch(e=>toast(e.message,'error'));});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});
const updateJobFormEvent=e=>Promise.resolve(handleUpdateJobFormEvent(e,{getState:()=>state,mutate,toast,showModal,closeModal,render})).catch(err=>toast(err.message,'error'));
document.addEventListener('input',updateJobFormEvent);
document.addEventListener('change',e=>{updateJobFormEvent(e);if(e.target.id==='table-file'){importRows=null;importFile=null;const b=document.querySelector('[data-action="execute-import"]');if(b)b.disabled=true;}if(e.target.dataset.selectId){if(e.target.checked)selected.add(e.target.dataset.selectId);else selected.delete(e.target.dataset.selectId);}if(e.target.hasAttribute('data-select-all')){selected=new Set(e.target.checked?filterResults.map(r=>r.id):[]);document.querySelectorAll('[data-select-id]').forEach(i=>i.checked=e.target.checked);}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(META[next]&&next!==page){page=next;render();}});
async function init(){try{const loaded=await jsonFetch('/api/state');revision=loaded.revision;state=loaded.state||createInitialState();const before=JSON.stringify(state);upgradeWorkspace(state);if(!loaded.state||before!==JSON.stringify(state))await save();render();}catch(e){$('#page-content').innerHTML=card('工作空间暂时无法读取',`<p class="text-danger">${esc(e.message)}</p><p class="subtle section-gap">请确认保存服务或浏览器存储可用后重新加载。</p>${btn('重新加载','reload','','primary')}`);document.querySelector('[data-action="reload"]').onclick=()=>location.reload();}}
setInterval(async()=>{if(!state||busy)return;const due=dueUpdateJob({...state,updateJobs:state.updateJobs.filter(job=>state.providers.some(p=>p.id===job.sourceId&&p.enabled&&p.connectionMode==='demo'))});if(due)await runUpdateJob(due.id,{scheduled:true});},30000);
init();
